import{_ as t,c as r,o as e,ag as o}from"./chunks/framework.Bkod66qp.js";const x=JSON.parse('{"title":"국외연수내규","description":"","frontmatter":{"title":"국외연수내규","subtitle":"","doc_id":"","last_update":"2014-11-19","author":"","categories":[],"tags":[]},"headers":[],"relativePath":"regulation/308_국외연수내규(141119).md","filePath":"regulation/308_국외연수내규(141119).md"}'),a={name:"regulation/308_국외연수내규(141119).md"};function i(d,l,s,p,n,c){return e(),r("div",null,l[0]||(l[0]=[o(`<h1 id="law-title" class="center" tabindex="-1">국외연수내규 <a class="header-anchor" href="#law-title" aria-label="Permalink to &quot;국외연수내규 {#law-title .center}&quot;">​</a></h1><div style="text-align:right;"><pre style="display:inline-block;margin:0;white-space:pre;font-family:monospace;">제정 2007.   7.  18
개정 2009.   3.   9
개정 2011.   4.   6
개정 2014.  11.  19</pre></div><h2 id="제1장-총-칙" tabindex="-1">제1장 총 칙 <a class="header-anchor" href="#제1장-총-칙" aria-label="Permalink to &quot;제1장 총 칙&quot;">​</a></h2><h2 id="article1" class="sr-only" tabindex="-1">제1조 (목적) <a class="header-anchor" href="#article1" aria-label="Permalink to &quot;제1조 (목적) {#article1 .sr-only}&quot;">​</a></h2><p><strong>제1조(목적)</strong> 이 내규는 재단법인서울문화재단 직원의 국외연수를 효율적으로 관리함으로서 국외연수를 통해 습득한 정보와 지식을 적절히 활용하여 자기 개발 및 직무수행에 대한 성취 동기 부여의 극대화를 목적으로 한다.</p><h2 id="article2" class="sr-only" tabindex="-1">제2조 (국외연수의 관장) <a class="header-anchor" href="#article2" aria-label="Permalink to &quot;제2조 (국외연수의 관장) {#article2 .sr-only}&quot;">​</a></h2><p><strong>제2조(국외연수의 관장)</strong> 소관부서는 직원의 국외연수에 관한 시행계획의 수립과 운영을 관장한다. &lt;개정 2009. 3. 9., 2011. 4. 6.&gt;</p><h2 id="article3" class="sr-only" tabindex="-1">제3조 (국외연수 담당직원) <a class="header-anchor" href="#article3" aria-label="Permalink to &quot;제3조 (국외연수 담당직원) {#article3 .sr-only}&quot;">​</a></h2><p><strong>제3조(국외연수 담당직원)</strong> 소관부서장은 직원 중에서 국외연수 관련 업무를 담당할 직원을 지정하여야 한다. &lt;개정 2009. 3. 9., 2011. 4. 6.&gt;</p><h2 id="article4" class="sr-only" tabindex="-1">제4조 (적용범위) <a class="header-anchor" href="#article4" aria-label="Permalink to &quot;제4조 (적용범위) {#article4 .sr-only}&quot;">​</a></h2><p><strong>제4조(적용범위)</strong> 이 내규는 임직원이 국외연수 명령의 결재를 득한 때부터 귀국보고를 완료한 때까지 적용함을 원칙으로 한다.</p><h2 id="article5" class="sr-only" tabindex="-1">제5조 (용어의 정의) <a class="header-anchor" href="#article5" aria-label="Permalink to &quot;제5조 (용어의 정의) {#article5 .sr-only}&quot;">​</a></h2><p><strong>제5조(용어의 정의)</strong> ① 이 내규에서 사용하는 용어인 “국외 연수”는 국외 단기연수 및 장기연수를 말한다.<br> ② 장기연수는 학위 취득을 목적으로 하는 유학을 포함한다.<br> ③ 단기연수는 6개월 내외, 장기연수는 2년 이내의 기간을 말한다.<br> ④ 15일 이내의 국외 여행(출장 포함)은 별도 내규로 시행한다.</p><h2 id="article6" class="sr-only" tabindex="-1">제6조 (사전승인) <a class="header-anchor" href="#article6" aria-label="Permalink to &quot;제6조 (사전승인) {#article6 .sr-only}&quot;">​</a></h2><p><strong>제6조(사전승인)</strong> ① 직원이 국외연수를 가고자 할 때는 재단에서 공지한 일정에 맞춰 별표 1 국외연수계획서를 작성하여, 담당 팀장의 확인을 받아 소관부서에 제출하고, 선정위원회의 승인을 득하여야 한다. &lt;개정 2009. 3. 9., 2011. 4. 6.&gt;<br> ② 국외연수 승인절차는 별표 2와 같다.</p><h2 id="article7" class="sr-only" tabindex="-1">제7조 (대상) <a class="header-anchor" href="#article7" aria-label="Permalink to &quot;제7조 (대상) {#article7 .sr-only}&quot;">​</a></h2><p><strong>제7조(대상)</strong> ① 장기연수는 입사 근속 3년 이상 직원에 한해 지원 신청 할 수 있다.<br> ② 단기연수는 입사 근속 2년 이상 직원에 한해 지원신청 할 수 있다.<br> ③ 국외연수는 년 1명 선발을 원칙으로 한다. 단, 같은 기간 내 연수 시행은 단기, 장기 포함하여 2인까지만 가능하다.<br> ④ 단기연수는 년 1-2명 내에서 필요에 따라 선발할 수 있다.</p><h2 id="article8" class="sr-only" tabindex="-1">제8조 (지원신청) <a class="header-anchor" href="#article8" aria-label="Permalink to &quot;제8조 (지원신청) {#article8 .sr-only}&quot;">​</a></h2><p><strong>제8조(지원신청)</strong> 국외연수 희망자가 계획서에 따른 각종 증빙자료를 첨부하여 소관부서에 제출하면, 소관부서는 선정위원회 소집을 요구한다. &lt;개정 2009. 3. 9., 2011. 4. 6.&gt;</p><h2 id="article9" class="sr-only" tabindex="-1">제9조 (지원시기) <a class="header-anchor" href="#article9" aria-label="Permalink to &quot;제9조 (지원시기) {#article9 .sr-only}&quot;">​</a></h2><p><strong>제9조(지원시기)</strong> 지원신청은 년1회 1월 중에 전 직원을 대상으로 공지한다.</p><h2 id="article10" class="sr-only" tabindex="-1">제10조 (연수시기) <a class="header-anchor" href="#article10" aria-label="Permalink to &quot;제10조 (연수시기) {#article10 .sr-only}&quot;">​</a></h2><p><strong>제10조(연수시기)</strong> 연수 시기는 당해 기간에 국외연수 중인 직원과 중복되지 않도록 한다. 단 준비과정이 필요한 경우 또는 이에 준하는 사유가 있을 경우 복귀 6개월 전부터 시행 가능하다.</p><h2 id="article11" class="sr-only" tabindex="-1">제11조 (심사) <a class="header-anchor" href="#article11" aria-label="Permalink to &quot;제11조 (심사) {#article11 .sr-only}&quot;">​</a></h2><p><strong>제11조(심사)</strong> 국외연수는 선정위원회에서 심사한다. 단, 단기연수의 경우 필요에 따라 대표이사가 결정할 수 있다.</p><h2 id="article12" class="sr-only" tabindex="-1">제12조 (선정위원회 구성) <a class="header-anchor" href="#article12" aria-label="Permalink to &quot;제12조 (선정위원회 구성) {#article12 .sr-only}&quot;">​</a></h2><p><strong>제12조(선정위원회 구성)</strong> 선정위원회는 인사위원회의 구성원과 동일하며, 필요에 따라 국외훈련의 전문성과 타당성 검토를 위해 자문 위원을 추가로 선임하여 위촉할 수 있다.</p><h2 id="article13" class="sr-only" tabindex="-1">제13조 (심사기준) <a class="header-anchor" href="#article13" aria-label="Permalink to &quot;제13조 (심사기준) {#article13 .sr-only}&quot;">​</a></h2><p><strong>제13조(심사기준)</strong> 선정위원회는 다음 각항을 심사기준으로 하여 결정한다.<br> ① 근무평정성적<br> ② 어학능력<br> ③ 국외훈련 계획의 타당성 및 기여도<br> ④ 기타 필요 사항</p><h2 id="article14" class="sr-only" tabindex="-1">제14조 (의결) <a class="header-anchor" href="#article14" aria-label="Permalink to &quot;제14조 (의결) {#article14 .sr-only}&quot;">​</a></h2><p><strong>제14조(의결)</strong> ① 선정위원회는 재적위원 3분의2 이상의 출석과 출석위원 과반 수 이상의 찬성으로 의결하며, 가부동수인 경우에는 부결된 것으로 본다.<br> ② 재단의 조직 및 업무 상황에 따라 선발하지 않을 수 있다.</p><h2 id="article15" class="sr-only" tabindex="-1">제15조 (경비지원) <a class="header-anchor" href="#article15" aria-label="Permalink to &quot;제15조 (경비지원) {#article15 .sr-only}&quot;">​</a></h2><p><strong>제15조(경비지원)</strong> ① 국외연수에 의한 휴직기간 동안 인사규정 제24조 제2항 제2호에 의해 그 기간 중에 연봉월액의 2할을 지급할 수 있다. 단, 장기연수의 경우 그 기간은 2년을 초과할 수 없다. &lt;개정 2014. 11. 19.&gt;<br> ② 국외연수에 소요되는 입학금, 등록금, 체재비, 기타 경비는 ①항과 별도로 당해 연도 예산범위 내에서 필요한 비용을 지급할 수 있다.</p><h2 id="article16" class="sr-only" tabindex="-1">제16조 (지급기준) <a class="header-anchor" href="#article16" aria-label="Permalink to &quot;제16조 (지급기준) {#article16 .sr-only}&quot;">​</a></h2><p><strong>제16조(지급기준)</strong> ① 제15조②항의 지급 기준 중에 등록금의 경우, 50% 내에서 지원할 수 있다. 다만 이는 예산허용범위 내에서만 가능하다.<br> ② 근속기간 10년 이상 근무자 중, 재단 발전에 기여하고 근무평정성적이 상위 10%에 해당하는 자는 예산범위 내에서 국외 연수 경비 전액을 지원할 수 있다.</p><h2 id="article17" class="sr-only" tabindex="-1">제17조 (국외연수명령) <a class="header-anchor" href="#article17" aria-label="Permalink to &quot;제17조 (국외연수명령) {#article17 .sr-only}&quot;">​</a></h2><p><strong>제17조(국외연수명령)</strong> 국외연수 명령은 선정위원회의 의결서 및 국외연수계획서를 첨부하여 대표이사가 국외연수 명령을 시달한다.</p><h2 id="article18" class="sr-only" tabindex="-1">제18조 (국외연수자의 준수사항) <a class="header-anchor" href="#article18" aria-label="Permalink to &quot;제18조 (국외연수자의 준수사항) {#article18 .sr-only}&quot;">​</a></h2><p><strong>제18조(국외연수자의 준수사항)</strong> ① 국외연수명령을 받은 직원은 재단법인서울문화재단의 명예와 긍지를 지키고 품위 있는 행동을 해야 한다.<br> ② 국외연수 중, 승인된 계획서의 변경사항이 발생할 경우에는 전송 또는 전화로 보고하여 승인을 득해야 한다.</p><h2 id="article19" class="sr-only" tabindex="-1">제19조 (복귀명령) <a class="header-anchor" href="#article19" aria-label="Permalink to &quot;제19조 (복귀명령) {#article19 .sr-only}&quot;">​</a></h2><p><strong>제19조(복귀명령)</strong> ① 국외연수자가 연수목적을 현저히 일탈하였거나 질병 또는 기타 부득이한 사고로 인하여 그 연수를 계속할 수 없게 된 경우에 대표이사는 복귀를 명령할 수 있다.<br> ② 연수자가 복귀명령을 받았을 때에는 지정된 기일까지 이에 응하여야 한다.</p><h2 id="article20" class="sr-only" tabindex="-1">제20조 (결과보고) <a class="header-anchor" href="#article20" aria-label="Permalink to &quot;제20조 (결과보고) {#article20 .sr-only}&quot;">​</a></h2><p><strong>제20조(결과보고)</strong> 국외연수를 마친 직원은 서약한 일자 내에 귀국함은 물론 30일 이내에 별표 3 결과보고서를 제출하여야 한다.</p><h2 id="article21" class="sr-only" tabindex="-1">제21조 (제한) <a class="header-anchor" href="#article21" aria-label="Permalink to &quot;제21조 (제한) {#article21 .sr-only}&quot;">​</a></h2><p><strong>제21조(제한)</strong> 기한 내에 결과보고서를 제대로 이행하지 않은 자에 대해서는 인사위원회의 의결을 통해 불이익을 줄 수 있다.</p><h2 id="article22" class="sr-only" tabindex="-1">제22조 (의무위반 등에 대한 조치) <a class="header-anchor" href="#article22" aria-label="Permalink to &quot;제22조 (의무위반 등에 대한 조치) {#article22 .sr-only}&quot;">​</a></h2><p><strong>제22조(의무위반 등에 대한 조치)</strong> ① 연수자가 다음에 해당하는 경우 재단에서 지원한 소요경비 전액을 반납하여야 한다.</p><ol><li>연수 중에 질병 또는 사고 등 부득이한 사유 이외의 사유로 인하여 퇴직할 때<br> ② 연수자가 다음에 해당하는 경우 재단에서 지원한 소요경비의 2배를 배상하여야 한다.</li><li>제19조 규정에 의해 복귀명령을 받고 정당한 사유 없이 지정된 기일까지 복귀하지 아니할 때</li><li>국외연수계획서와 이행 내용이 현저히 다를 때</li><li>별표 4 서약서를 위반 한 때</li><li>의무 복무를 이행하지 아니한 때</li></ol><h2 id="article23" class="sr-only" tabindex="-1">제23조 (복무의무) <a class="header-anchor" href="#article23" aria-label="Permalink to &quot;제23조 (복무의무) {#article23 .sr-only}&quot;">​</a></h2><p><strong>제23조(복무의무)</strong> ① 장기연수를 다녀온 자는 종료일부터 기산하여 3년간 의무복무 하여야 하며, 단기연수를 다녀온 자는 종료일부터 1년간 의무복무 하여야 한다.<br> ② 의무복무기간 만료 전에 다시 단기 또는 장기연수를 이수한 직원에 대한 의무복무기간은 최대의무복무기간 하나만 적용한다.</p><h2 id="article24" class="sr-only" tabindex="-1">제24조 (기간) <a class="header-anchor" href="#article24" aria-label="Permalink to &quot;제24조 (기간) {#article24 .sr-only}&quot;">​</a></h2><p><strong>제24조(기간)</strong> 장기연수에 의한 휴직기간은 2년 이내로 하되, 학위 취득을 목적으로 하는 유학의 경우에는 1년 범위 안에서 연장할 수 있다.</p><h2 id="addendum1" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum1" aria-label="Permalink to &quot;부칙 {#addendum1 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong><br> 제1조(시행일) 이 내규는 대표이사의 승인을 얻은 날로부터 시행한다.</p><p><strong>[별표 1]</strong></p><p>국외연수계획서</p><ol><li>연수목적 및 필요성</li></ol><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:577px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></th></tr></table><ol start="2"><li>연수기간 및 일정</li></ol><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:575px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></th></tr></table><ol start="3"><li>연수국가 및 기관</li></ol><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:575px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></th></tr></table><ol start="4"><li>세부 연수 내용</li></ol><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:575px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></th></tr></table><ol start="5"><li>기 타</li></ol><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:575px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></th></tr></table><p><strong>[별표 2]</strong></p><p>승인 절차</p><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:341px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">공 지</p></th></tr><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">⇩</p></th></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">계획서 제출</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">⇩</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">선정위원회 심의</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">⇩</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">선 정</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">⇩</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">단기, 장기연수 추진</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">⇩</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">연 수</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">⇩</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">복 귀</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">⇩</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">결과 보고</p></td></tr></table><p><strong>[별표 3]</strong></p><p>국외연수 결과보고서</p><ol><li>연수개요</li></ol><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:577px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">연수자 인적사항, 연수국가, 기간, 과정, 목적 등을 개조식으로 기술</p><p style="margin:0;text-align:left;"></p></th></tr></table><ol start="2"><li>연수국가의 일반현황</li></ol><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:575px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">연수국가의 정치, 경제, 사회, 문화, 역사, 지리, 행정제도 등 일반적인 국가현황을 개조식으로 약술</p><p style="margin:0;text-align:left;"></p></th></tr></table><ol start="3"><li>연수내용(본론)</li></ol><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:575px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">연수받은 내용을 단원별로 구분하여 구체적으로 기술</p><p style="margin:0;text-align:left;"></p></th></tr></table><ol start="4"><li>연수성과</li></ol><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:575px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">새로운 기술 및 지식습득내용 기술</p><p style="margin:0;text-align:left;"></p></th></tr></table><ol start="5"><li>기타의견 및 건의사항</li></ol><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:575px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></th></tr></table><p><strong>[별표 4]</strong></p><p>서 약 서</p><p>본인은 재단법인서울문화재단 직원해외연수 대상자로 선발되어 년 월 일부터 년 월 일까지 대학(원)의 연수를 수행함에 있어서 다음 사항을 성실히 준수할 것을 확약합니다.</p><ol><li><p>연수기간 중 대한민국과 서울특별시를 대표하는 문화예술기관 직원으로서의 품위유지 및 국위선양을 위해 노력하고 제규정과 의무를 엄수하며 업무상 지득한 비밀을 일절 누설하지 않겠음. 만일 이에 위배되는 행위로 인하여 발생하는 모든 손해에 대해서는 민·형사를 막론하고 책임을 감수하겠음.</p></li><li><p>연수중에는 임의로 연수지를 이탈하거나 사직하지 않으며, 전보 또는 복귀조치 등 회사의 명령에 절대 따르겠음. 한편 질병이나 사고 등의 부득이한 사유 외에 사직 또는 회사 명령에 불복하여 면직·해고되는 경우와 복귀 후 연수중에 발생한 사유로 인하여 면직·해고되는 경우에는 이의를 제기하지 않겠으며, 이 경우 본인의 해외연수를 위하여 회사에서 지원하고 부담한 비용을 규정에 따라 반납하겠음.</p></li><li><p>연수 중 질병이나 사고 등 신상의 변화, 소재지 변경, 연수경비에 대한 외부의 찬조나 기부금 또는 장학금 수령 등 연수관리에 필요한 사항에 대하여 지체없이 보고하도록 하고, 전심전력을 다하여 우수한 성적으로 연수과정을 이수, 귀국 후에는 습득한 전문지식과 경험을 바탕으로 재단 발전을 위해 최대한 기여하겠으며, 규정된 의무나 지시사항에 위반하여 중도에 복귀되거나 특별한 사유없이 중도에 연수를 포기 또는 탈락되는 경우에는 재단에서 지원하고 부담한 비용을 규정에 의해 반납하겠음.</p></li><li><p>연수과정이 종료되면 지체없이 복직을 신청하고, 회사의 명에 따라 보직을 받으며 이후 의무복무 기간(장기연수-3년, 단기연수-1년) 동안의 복무의무를 이행하지 않을 경우에는 연수기간 동안 재단에서 지원하고 부담한 비용 일체에 대하여 규정에 의해 반납하겠음. 끝.</p></li></ol><p style="text-align:center;">년 월 일</p><p style="text-align:center;">직원 국외연수 대상자 (인/서명)</p>`,87)]))}const g=t(a,[["render",i]]);export{x as __pageData,g as default};
